const items = $input.all();
const output = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const jobs = body.jobs || [];

  for (const job of jobs) {
    const title = (job.title || '').toLowerCase();
    const location = (job.location?.name || '').toLowerCase();

    // Filter criteria: remote/US and target engineering roles
    const isRemote = location.includes('remote') || location.includes('anywhere') || location.includes('us');
    const isTargetRole = title.includes('systems') || title.includes('infrastructure') || title.includes('distributed') || title.includes('staff') || title.includes('platform');

    if (isRemote && isTargetRole) {
      // Calculate basic heuristic match score
      let score = 80;
      if (title.includes('staff') || title.includes('principal')) score += 10;
      if (title.includes('distributed') || title.includes('systems')) score += 6;

      output.push({
        json: {
          id: 'gh-' + job.id,
          company: 'Anthropic',
          title: job.title,
          location: job.location?.name || 'Remote',
          board_type: 'greenhouse',
          external_url: job.absolute_url,
          match_score: Math.min(score, 99),
          updated_at: job.updated_at
        }
      });
    }
  }
}

return output;
